Object.assign(sandbox.S,{meta:D.meta,elements:D.elements,presentation:D.presentation,calculations:D.calculations,definitions:D.definitions,rules:D['business-rules'],elrs:D.elrs});
const roles=new Set(D.elrs.map(e=>e.name));
const models=sandbox.all();
assert.strictEqual(models.length,92,'all hosted table models');
assert(models.every(m=>m.lineItems.length>0),'every table has line items');
function find(q){return models.find(m=>m.tableQ===q)}
for(const q of ['in-gaap:LoansAndAdvancesTable','in-gaap:DetailsOfGoodsPurchasedTable','in-gaap:DetailsOfManufacturedAndTradedGoodsTable','in-gaap:DetailsOfWorkInProgressTable']){
 const m=find(q); assert(m, q+' missing'); assert(m.lineItems.length>0,q+' no line items');
 console.log(q,'role=',m.role,'lineItems=',m.lineItems.length);
}
function hostFor(q,concept) {
 for(const role of roles) {
   const m=sandbox.models(role).find(x=>x.tableQ===q);
   if(m && m.lineItems.some(li=>li.q===concept)) return role;
 }
 return null;
}
assert.strictEqual(hostFor('in-gaap:LoansAndAdvancesTable','in-gaap:LoansAndAdvancesGross'),'[200600] Notes - Subclassification and notes on liabilities and assets');
assert.strictEqual(hostFor('in-gaap:DetailsOfGoodsPurchasedTable','in-gaap:DescriptionOfGoodsPurchased'),'[300600] Notes - Additional information statement of profit and loss');
assert.strictEqual(hostFor('in-gaap:DetailsOfManufacturedAndTradedGoodsTable','in-gaap:DescriptionOfFinishedGoods'),'[300600] Notes - Additional information statement of profit and loss');
assert.strictEqual(hostFor('in-gaap:DetailsOfWorkInProgressTable','in-gaap:DescriptionOfWorkInProgress'),'[300600] Notes - Additional information statement of profit and loss');

const notes200600=sandbox.models('[200600] Notes - Subclassification and notes on liabilities and assets');
assert(sandbox.forConcept('[200600] Notes - Subclassification and notes on liabilities and assets','in-gaap:LoansAndAdvancesGross')?.tableQ==='in-gaap:LoansAndAdvancesTable','concept resolver Loans');
assert(sandbox.forConcept('[300600] Notes - Additional information statement of profit and loss','in-gaap:DescriptionOfGoodsPurchased')?.tableQ==='in-gaap:DetailsOfGoodsPurchasedTable','concept resolver Goods');
assert(sandbox.forConcept('[300600] Notes - Additional information statement of profit and loss','in-gaap:DescriptionOfFinishedGoods')?.tableQ==='in-gaap:DetailsOfManufacturedAndTradedGoodsTable','concept resolver Manufactured');
assert(sandbox.forConcept('[300600] Notes - Additional information statement of profit and loss','in-gaap:DescriptionOfWorkInProgress')?.tableQ==='in-gaap:DetailsOfWorkInProgressTable','concept resolver WIP');
assert(notes200600.some(m=>m.tableQ==='in-gaap:LoansAndAdvancesTable'),'Loans and advances hosted in 200600');
const notes300600=sandbox.models('[300600] Notes - Additional information statement of profit and loss');
for(const q of ['in-gaap:DetailsOfRawMaterialsConsumedTable','in-gaap:DetailsOfGoodsPurchasedTable','in-gaap:DetailsOfManufacturedAndTradedGoodsTable','in-gaap:DetailsOfWorkInProgressTable']){
 assert(notes300600.some(m=>m.tableQ===q),q+' hosted in 300600');
}

for(const role of roles){ const seen=new Set(sandbox.models(role).map(m=>m.id)); for(const m of models) if(m.role===role) assert(seen.has(m.id)); }
console.log('PASS: V22 hosted table model resolution');
